(function () {
    'use strict';

    const SCRIPT_NAME = '双马尾插件（免费发布与防骗公告）';
    const VERSION = '9.9.9';
    const SCRIPT_ID = '5ded9f42-51af-4026-bfe6-05712d91db24';

    const API_NAME = '__twintailPlugin__';
    const LEGACY_API_NAME = '__unicodeFloorInterceptor__';
    const LOADED_FLAG = '__twintailPlugin_loaded__';
    const STATE_NAME = '__twintailPlugin_state__';
    const INSTANCE_ID = `tt-notice-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;

    const PANEL_ID = 'twintail-notice-modal';
    const STYLE_ID = 'twintail-notice-style';
    const MENU_ITEM_ID = 'tt-notice-ext-menu-item';
    const LAUNCHER_BUTTON_NAME = '⚙ 双马尾插件';
    const MUTE_STORAGE_KEY = 'twintail-plugin:anti-scalper-notice:muted:v1';

    const NOTICE_HEADLINE = '本插件仅在类脑免费发布，警惕贩子倒卖，若你是付费获得，说明你被骗了，请立即联系退款。';

    const LEGACY_DOM_IDS = Object.freeze([
        'twintail-console-panel',
        'twintail-console-style',
        'twintail-floating-fab',
        'tt-qr-bar-btn',
        'tt-ext-menu-item',
        'tt-custom-qr-strip',
    ]);

    const runtime = {
        disposed: false,
        modal: null,
        style: null,
        lastFocused: null,
        stops: [],
    };

    function hostWindows() {
        const chain = [];
        const pushIfNew = win => {
            if (win && chain.indexOf(win) === -1) chain.push(win);
        };
        pushIfNew(window);
        try {
            let cur = window;
            for (let hop = 0; hop < 6; hop += 1) {
                const parentRef = cur.parent;
                if (!parentRef || parentRef === cur) break;
                pushIfNew(parentRef);
                cur = parentRef;
            }
        } catch (_) {}
        try { pushIfNew(window.top); } catch (_) {}
        return chain;
    }

    function rootWindow() {
        const chain = hostWindows();
        return chain.length ? chain[chain.length - 1] : window;
    }

    function scoreStDocument(doc) {
        if (!doc?.body) return 0;
        let score = 0;
        try {
            if (doc.getElementById('send_form')) score += 8;
            if (doc.getElementById('send_textarea')) score += 4;
            if (doc.getElementById('sheld')) score += 4;
            if (doc.getElementById('qr--bar')) score += 2;
            if (doc.getElementById('chat')) score += 1;
        } catch (_) {}
        return score;
    }

    function hostDocument() {
        const candidates = [];
        for (const win of hostWindows()) {
            try {
                const doc = win?.document;
                if (doc?.documentElement && candidates.indexOf(doc) === -1) {
                    candidates.push(doc);
                }
            } catch (_) {}
        }
        let best = null;
        let bestScore = 0;
        for (const doc of candidates) {
            const s = scoreStDocument(doc);
            if (s > bestScore) {
                bestScore = s;
                best = doc;
            }
        }
        return best
            || candidates.find(d => d.body && d !== document)
            || candidates.find(d => d.body)
            || candidates[0]
            || document;
    }

    function storageRef() {
        try {
            const topWin = rootWindow();
            if (topWin?.localStorage) return topWin.localStorage;
        } catch (_) {}
        try {
            const doc = hostDocument();
            if (doc?.defaultView?.localStorage) return doc.defaultView.localStorage;
        } catch (_) {}
        try { return window.localStorage || null; } catch (_) { return null; }
    }

    function isNoticeMuted() {
        try {
            return storageRef()?.getItem(MUTE_STORAGE_KEY) === '1';
        } catch (_) {
            return false;
        }
    }

    function setNoticeMuted(muted) {
        try {
            const store = storageRef();
            if (!store) return;
            if (muted) store.setItem(MUTE_STORAGE_KEY, '1');
            else store.removeItem(MUTE_STORAGE_KEY);
        } catch (_) {}
    }

    function notify(level, message, title = SCRIPT_NAME) {
        const kind = (level === 'success' || level === 'warning' || level === 'error' || level === 'info')
            ? level
            : 'warning';
        for (const win of hostWindows()) {
            try {
                const api = win?.toastr;
                if (api && typeof api[kind] === 'function') {
                    api[kind](String(message ?? ''), title, { timeOut: 12000, extendedTimeOut: 6000 });
                    return;
                }
            } catch (_) {}
        }
        const logger = kind === 'error' ? console.error : (kind === 'warning' ? console.warn : console.log);
        logger(`[${title}] ${message}`);
    }

    function toolbarApi() {
        const bindFrom = (obj, fnName) => (typeof obj?.[fnName] === 'function' ? obj[fnName].bind(obj) : null);
        const candidates = [];
        try {
            const localTh = typeof TavernHelper !== 'undefined' ? TavernHelper : null;
            candidates.push({
                eventOn: typeof eventOn === 'function' ? eventOn : bindFrom(localTh, 'eventOn'),
                getButtonEvent: typeof getButtonEvent === 'function' ? getButtonEvent : bindFrom(localTh, 'getButtonEvent'),
                appendButtons: typeof appendInexistentScriptButtons === 'function'
                    ? appendInexistentScriptButtons
                    : (bindFrom(localTh, 'appendInexistentScriptButtons') || bindFrom(localTh, 'replaceScriptButtons')),
                getButtons: typeof getScriptButtons === 'function' ? getScriptButtons : bindFrom(localTh, 'getScriptButtons'),
                replaceButtons: typeof replaceScriptButtons === 'function' ? replaceScriptButtons : bindFrom(localTh, 'replaceScriptButtons'),
            });
        } catch (_) {}
        for (const win of hostWindows()) {
            try {
                const th = win?.TavernHelper;
                candidates.push({
                    eventOn: bindFrom(win, 'eventOn') || bindFrom(th, 'eventOn'),
                    getButtonEvent: bindFrom(win, 'getButtonEvent') || bindFrom(th, 'getButtonEvent'),
                    appendButtons: bindFrom(win, 'appendInexistentScriptButtons')
                        || bindFrom(th, 'appendInexistentScriptButtons')
                        || bindFrom(win, 'replaceScriptButtons')
                        || bindFrom(th, 'replaceScriptButtons'),
                    getButtons: bindFrom(win, 'getScriptButtons') || bindFrom(th, 'getScriptButtons'),
                    replaceButtons: bindFrom(win, 'replaceScriptButtons') || bindFrom(th, 'replaceScriptButtons'),
                });
            } catch (_) {}
        }
        return candidates.find(item => item.eventOn && item.getButtonEvent) || null;
    }

    function copyText(text) {
        const doc = hostDocument();
        const view = doc?.defaultView || rootWindow();
        if (view?.navigator?.clipboard?.writeText) {
            return view.navigator.clipboard.writeText(text).then(() => true).catch(() => fallbackCopy(doc, text));
        }
        return Promise.resolve(fallbackCopy(doc, text));
    }

    function fallbackCopy(doc, text) {
        try {
            if (!doc?.body) return false;
            const ta = doc.createElement('textarea');
            ta.value = text;
            ta.setAttribute('readonly', 'readonly');
            ta.style.cssText = 'position:fixed;left:-9999px;top:-9999px;opacity:0;';
            doc.body.appendChild(ta);
            ta.select();
            const ok = doc.execCommand ? doc.execCommand('copy') : false;
            ta.remove();
            return Boolean(ok);
        } catch (_) {
            return false;
        }
    }

    function noticeCss() {
        return `
#${PANEL_ID}{
  position:fixed;inset:0;z-index:2147483646;display:none;align-items:center;justify-content:center;
  padding:16px;background:rgba(4,7,13,.8);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);
  box-sizing:border-box;font-family:"Inter",ui-sans-serif,system-ui,-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;
  color:#f1f5f9;
}
#${PANEL_ID}.open{display:flex;}
#${PANEL_ID} *, #${PANEL_ID} *::before, #${PANEL_ID} *::after{box-sizing:border-box;}
#${PANEL_ID} .ttn-card{
  width:min(520px,100%);max-height:min(88vh,680px);overflow:auto;
  background:#111722;border:1px solid rgba(248,113,113,.45);border-radius:16px;
  box-shadow:0 28px 80px rgba(0,0,0,.78);padding:20px 22px 18px;
}
#${PANEL_ID} .ttn-top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;}
#${PANEL_ID} .ttn-badge{
  display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;
  background:rgba(239,68,68,.18);border:1px solid rgba(248,113,113,.45);
  color:#fca5a5;font-size:12px;font-weight:700;letter-spacing:.02em;
}
#${PANEL_ID} .ttn-close{
  width:30px;height:30px;border-radius:8px;border:1px solid rgba(148,163,184,.25);
  background:rgba(30,41,59,.75);color:#cbd5e1;font-size:18px;line-height:1;cursor:pointer;
}
#${PANEL_ID} .ttn-close:hover{background:rgba(51,65,85,.95);color:#fff;}
#${PANEL_ID} .ttn-title{font-size:18px;font-weight:800;line-height:1.4;color:#fef2f2;margin:0 0 12px;}
#${PANEL_ID} .ttn-alert{
  padding:14px 15px;border-radius:12px;margin-bottom:14px;
  background:linear-gradient(135deg,rgba(239,68,68,.18),rgba(245,158,11,.12));
  border:1px solid rgba(248,113,113,.42);color:#fee2e2;
  font-size:15px;font-weight:700;line-height:1.65;
}
#${PANEL_ID} .ttn-desc{
  font-size:13px;line-height:1.65;color:#cbd5e1;margin:0 0 12px;
}
#${PANEL_ID} .ttn-box{
  padding:11px 13px;border-radius:10px;background:rgba(15,23,42,.78);
  border:1px solid rgba(148,163,184,.18);font-size:12.5px;line-height:1.6;color:#94a3b8;margin-bottom:14px;
}
#${PANEL_ID} .ttn-box strong{color:#e2e8f0;}
#${PANEL_ID} .ttn-mute{
  display:flex;align-items:center;gap:8px;font-size:12.5px;color:#94a3b8;
  margin-bottom:14px;cursor:pointer;user-select:none;
}
#${PANEL_ID} .ttn-mute input{width:16px;height:16px;accent-color:#ef4444;cursor:pointer;}
#${PANEL_ID} .ttn-actions{display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-end;}
#${PANEL_ID} .ttn-btn{
  height:36px;padding:0 15px;border-radius:9px;border:1px solid rgba(148,163,184,.28);
  background:#1e293b;color:#e2e8f0;font:inherit;font-size:13px;font-weight:700;cursor:pointer;
}
#${PANEL_ID} .ttn-btn:hover{background:#334155;color:#fff;}
#${PANEL_ID} .ttn-btn.primary{
  background:#ef4444;border-color:transparent;color:#fff;
}
#${PANEL_ID} .ttn-btn.primary:hover{background:#dc2626;}
`;
    }

    function ensureModal() {
        const doc = hostDocument();
        if (!doc?.body) return null;
        if (runtime.modal?.isConnected && runtime.modal.ownerDocument === doc) {
            return runtime.modal;
        }
        try { doc.getElementById(PANEL_ID)?.remove(); } catch (_) {}
        try { doc.getElementById(STYLE_ID)?.remove(); } catch (_) {}

        const style = doc.createElement('style');
        style.id = STYLE_ID;
        style.dataset.instanceId = INSTANCE_ID;
        style.textContent = noticeCss();
        (doc.head || doc.documentElement).appendChild(style);
        runtime.style = style;

        const overlay = doc.createElement('div');
        overlay.id = PANEL_ID;
        overlay.dataset.instanceId = INSTANCE_ID;
        overlay.setAttribute('aria-hidden', 'true');
        overlay.innerHTML = [
            '<div class="ttn-card" role="dialog" aria-modal="true" aria-labelledby="ttn-dialog-title">',
            '  <div class="ttn-top">',
            '    <span class="ttn-badge">⚠ 官方免费声明 · 防倒卖公告</span>',
            '    <button class="ttn-close" type="button" data-action="close" aria-label="关闭">×</button>',
            '  </div>',
            '  <h2 class="ttn-title" id="ttn-dialog-title">双马尾插件重要公告</h2>',
            `  <div class="ttn-alert">${NOTICE_HEADLINE}</div>`,
            '  <p class="ttn-desc">由于本插件遭到不法贩子盗用与倒卖，旧自动更新仓库已停用并切换为纯公告版（原拦截/防路由功能已在本公告包中停止）。</p>',
            '  <div class="ttn-box">',
            '    <div>1. <strong>免费获取正版：</strong>请前往<strong>类脑</strong>原发布帖免费获取最新版本并重新导入。</div>',
            '    <div>2. <strong>遭遇倒卖维权：</strong>如你在闲鱼、电商平台、QQ群或第三方处付费购买，请立即保留订单与聊天截图申请退款。</div>',
            '    <div>3. <strong>清理本公告脚本：</strong>可在「酒馆助手 → 脚本管理」中关闭或删除本脚本后，导入类脑最新正版脚本。</div>',
            '  </div>',
            '  <label class="ttn-mute">',
            '    <input type="checkbox" data-role="muteAutoPopup">',
            '    <span>下次刷新不再自动弹出（仍可通过「⚙ 双马尾插件」按钮或扩展菜单重新查看）</span>',
            '  </label>',
            '  <div class="ttn-actions">',
            '    <button class="ttn-btn" type="button" data-action="copy">复制防骗声明</button>',
            '    <button class="ttn-btn primary" type="button" data-action="close">我已知晓，关闭</button>',
            '  </div>',
            '</div>',
        ].join('\n');

        const onClick = ev => {
            if (ev.target === overlay || ev.target?.closest?.('[data-action="close"]')) {
                closeNoticeModal();
                return;
            }
            if (ev.target?.closest?.('[data-action="copy"]')) {
                copyText(NOTICE_HEADLINE).then(ok => {
                    notify(ok ? 'success' : 'warning', ok ? '已复制公告声明内容' : '复制失败，请手动选中文本复制');
                });
            }
        };
        const onChange = ev => {
            const target = ev.target;
            if (target?.matches?.('[data-role="muteAutoPopup"]')) {
                setNoticeMuted(target.checked === true);
            }
        };
        const onKeyDown = ev => {
            if (ev.key === 'Escape' && overlay.classList.contains('open')) {
                closeNoticeModal();
            }
        };

        overlay.addEventListener('click', onClick);
        overlay.addEventListener('change', onChange);
        doc.addEventListener('keydown', onKeyDown, true);
        runtime.stops.push(
            () => overlay.removeEventListener('click', onClick),
            () => overlay.removeEventListener('change', onChange),
            () => doc.removeEventListener('keydown', onKeyDown, true),
        );

        doc.body.appendChild(overlay);
        runtime.modal = overlay;
        return overlay;
    }

    function openNoticeModal() {
        if (runtime.disposed) return false;
        const overlay = ensureModal();
        if (!overlay) return false;
        const doc = overlay.ownerDocument;
        runtime.lastFocused = doc.activeElement || null;
        const muteBox = overlay.querySelector('[data-role="muteAutoPopup"]');
        if (muteBox) muteBox.checked = isNoticeMuted();
        overlay.classList.add('open');
        overlay.setAttribute('aria-hidden', 'false');
        try { overlay.querySelector('[data-action="close"]')?.focus?.({ preventScroll: true }); } catch (_) {}
        return true;
    }

    function closeNoticeModal() {
        const overlay = runtime.modal;
        if (!overlay) return;
        overlay.classList.remove('open');
        overlay.setAttribute('aria-hidden', 'true');
        const target = runtime.lastFocused;
        runtime.lastFocused = null;
        try { target?.focus?.({ preventScroll: true }); } catch (_) {}
    }

    function cleanupLegacyArtifacts() {
        for (const doc of hostWindows().map(w => { try { return w?.document; } catch (_) { return null; } }).filter(Boolean)) {
            for (const id of LEGACY_DOM_IDS) {
                try { doc.getElementById(id)?.remove?.(); } catch (_) {}
            }
        }
    }

    function mountEntryPoints() {
        try {
            const api = toolbarApi();
            if (api) {
                try { api.appendButtons?.([{ name: LAUNCHER_BUTTON_NAME, visible: true }]); } catch (_) {}
                const stop = api.eventOn(api.getButtonEvent(LAUNCHER_BUTTON_NAME), openNoticeModal);
                if (typeof stop === 'function') runtime.stops.push(stop);
                else if (stop && typeof stop.stop === 'function') runtime.stops.push(() => stop.stop());
            }
        } catch (_) {}

        const doc = hostDocument();
        try {
            const extMenu = doc?.getElementById?.('extensionsMenu');
            if (extMenu) {
                try { doc.getElementById(MENU_ITEM_ID)?.remove?.(); } catch (_) {}
                const item = doc.createElement('div');
                item.id = MENU_ITEM_ID;
                item.className = 'list-group-item flex-container flexGap5 interactable';
                item.tabIndex = 0;
                item.innerHTML = '<span style="font-weight:700">⚠</span><span>双马尾插件防骗公告</span>';
                const onMenuClick = () => openNoticeModal();
                item.addEventListener('click', onMenuClick);
                extMenu.appendChild(item);
                runtime.stops.push(() => {
                    item.removeEventListener('click', onMenuClick);
                    item.remove();
                });
            }
        } catch (_) {}
    }

    function dispose(reason = 'manual') {
        if (runtime.disposed) return;
        runtime.disposed = true;
        while (runtime.stops.length) {
            try { runtime.stops.pop()(); } catch (_) {}
        }
        try { runtime.modal?.remove?.(); } catch (_) {}
        try { runtime.style?.remove?.(); } catch (_) {}
        runtime.modal = null;
        runtime.style = null;
        const topHost = rootWindow();
        for (const key of [API_NAME, LEGACY_API_NAME, STATE_NAME]) {
            if (topHost[key]?.instanceId === INSTANCE_ID) {
                try { delete topHost[key]; } catch (_) { topHost[key] = undefined; }
            }
        }
        topHost[LOADED_FLAG] = false;
        console.log(`[${SCRIPT_NAME}] 已卸载：${reason}`);
    }

    function exposeApi() {
        const host = rootWindow();
        const api = {
            instanceId: INSTANCE_ID,
            version: VERSION,
            scriptId: SCRIPT_ID,
            openPanel: openNoticeModal,
            closePanel: closeNoticeModal,
            openNotice: openNoticeModal,
            checkForUpdate: () => {
                openNoticeModal();
                notify('warning', NOTICE_HEADLINE);
                return Promise.resolve({ ok: true, noticeOnly: true, version: VERSION });
            },
            dispose,
        };
        Object.assign(host, {
            [API_NAME]: api,
            [LEGACY_API_NAME]: api,
            [LOADED_FLAG]: true,
            [STATE_NAME]: { instanceId: INSTANCE_ID, mountedAt: Date.now(), noticeOnly: true },
        });
    }

    function init() {
        const host = rootWindow();
        for (const prevKey of [API_NAME, LEGACY_API_NAME]) {
            const prev = host[prevKey];
            if (prev && prev.instanceId !== INSTANCE_ID) {
                try { prev.dispose?.('replaced'); } catch (_) {}
            }
        }
        cleanupLegacyArtifacts();
        exposeApi();
        mountEntryPoints();
        try { window.addEventListener('pagehide', () => dispose('pagehide'), { once: true }); } catch (_) {}

        notify('warning', NOTICE_HEADLINE);
        if (!isNoticeMuted()) {
            openNoticeModal();
        }
        console.log(`[${SCRIPT_NAME}] v${VERSION} 已加载：${NOTICE_HEADLINE}`);
    }

    setTimeout(() => {
        try {
            init();
        } catch (err) {
            console.error(`[${SCRIPT_NAME}] 初始化失败`, err);
            notify('warning', NOTICE_HEADLINE);
        }
    }, 0);
})();
